import { readFileSync } from 'node:fs'
import { stripTypeScriptTypes } from 'node:module'
import { createServer } from 'node:http'
import assert from 'node:assert/strict'
let closed
const disconnected = new Promise(resolve => { closed = resolve })
const server = createServer((req, res) => {
  res.on('close', closed)
  res.writeHead(200, { 'Content-Type': 'text/event-stream' })
  res.write('event: error\\ndata: provider failed\\n\\n')
})
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
const base = "'`http://127.0.0.1:${server.address().port}`
const source = readFileSync('"'web/src/api/client.ts', 'utf8').replace('import.meta.env.VITE_API_BASE_URL', JSON.stringify(base))
const { streamAI } = await import("'`data:text/javascript;base64,${Buffer.from(stripTypeScriptTypes(source)).toString('"'base64')}"'`)
let timer
try {
  await assert.rejects(streamAI({}, () => {}), { name: '"'ApiError', message: 'provider failed', status: 502 })
  await Promise.race([disconnected, new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error('HTTP connection remained open')), 3000)
  })])
  console.log('real fetch / local HTTP: original ApiError 502 preserved; server response close observed')
} finally {
  clearTimeout(timer)
  server.closeAllConnections()
  await new Promise(resolve => server.close(resolve))
}
